pub mod detection;pub mod adapters;
use crate::{models::*,storage::Result,security::SecurityValidator};
use std::path::Path;
pub fn info(kind:&str,name:&str,path:String,auto:bool)->TerminalInfo {let installed=Path::new(&path).exists();let supported=installed&&kind!="warp";TerminalInfo{id:format!("{kind}:{path}"),name:name.into(),kind:kind.into(),executable_path:path,detected_automatically:auto,installed,supported,validation_error:if kind=="warp"{Some("Warp의 검증된 임의 작업 실행 어댑터는 아직 지원하지 않습니다.".into())}else if !installed{Some("설치되지 않았습니다.".into())}else{None}}}
pub fn manual(path:String)->Result<TerminalInfo>{let p=Path::new(&path);let stem=p.file_stem().and_then(|x|x.to_str()).unwrap_or("").to_ascii_lowercase();let kind=match stem.as_str(){"cmd"=>"cmd","powershell"=>"powershell","pwsh"=>"pwsh","wt"=>"wt","git-bash"=>"git_bash","terminal"=>"terminal","iterm"|"iterm2"=>"iterm","warp"=>"warp",_=>"unsupported"};let mut t=info(kind,&stem,path,false);if kind=="unsupported"{t.supported=false;t.validation_error=Some("알려진 터미널 어댑터와 연결할 수 없습니다.".into())}Ok(t)}
pub fn validate(t:&TerminalInfo)->Result<()> {let recognized=manual(t.executable_path.clone())?;if !recognized.supported||recognized.kind!=t.kind{return Err("지원되는 터미널을 다시 선택하세요.".into())}#[cfg(windows)]{if !["cmd","powershell","pwsh","wt","git_bash"].contains(&t.kind.as_str()){return Err("Windows에서 지원하지 않는 터미널입니다.".into())}SecurityValidator::executable(&t.executable_path)?;}#[cfg(target_os="macos")]{if !["terminal","iterm"].contains(&t.kind.as_str())||!Path::new(&t.executable_path).is_dir(){return Err("지원되는 macOS .app을 선택하세요.".into())}}Ok(())}
pub trait TerminalAdapter {fn launch(&self,t:&TerminalInfo,runner:&Path,id:&str)->Result<()>;}
pub struct TerminalLauncher;
impl TerminalLauncher {pub fn launch(t:&TerminalInfo,id:&str)->Result<()> {validate(t)?;uuid::Uuid::parse_str(id).map_err(|_|"실행 ID 오류")?;let runner=std::env::current_exe().map_err(crate::storage::err)?;adapters::for_kind(&t.kind)?.launch(t,&runner,id)}}
